    }
    Map<V, V> vertexMap = new HashMap<>();
    for (V vertex : graph.vertexSet()) {
        vertexMap.put(vertex, vertex);
    }
    return new IsomorphicGraphMapping<>(graph, graph, vertexMap);
}

public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    return new IsomorphicGraphMapping<V,E>() {
        @Override
        public boolean isIdentity() {
            return true;
        }

        @Override
        public V getVertexCorrespondence(V vertex, boolean forward) {
            if (!graph.containsVertex(vertex)) {
                throw new IllegalArgumentException("Vertex " + vertex + " is not part of the graph");
