public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    try {
        if (file.isDirectory()) {
            File[] files = file.listFiles();
            if (files != null) {
                for (File f : files) {
                    forceDeleteOnExit(f);
                }
            }
        }
        file.deleteOnExit();
    } catch (Exception e) {
        throw new IOException("Failed to schedule file for deletion on exit: " + file.getAbsolutePath(), e);
    }
}

