public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        final byte[] delimBuffer = new byte[5];
        int size = ProtobufOutput.computeSerializedSize(message, schema);
        int delimSize = CodedOutputStream.computeRawVarint32Size(size);

        CodedOutputStream.putVarint32(delimBuffer, 0, size);
        out.write(delimBuffer, 0, delimSize);

        ProtobufOutput.writeTo(out, message, schema, buffer);

        return size + delimSize;
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("Error serializing message", e);
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
