        throw new NullPointerException("Message cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new NullPointerException("Buffer cannot be null");
    }

    final byte[] data;
    try {
        data = schema.writeTo(buffer, message);
    } finally {
        buffer.clear();
    }

    // Write the length of the message as a varint
    ProtostuffIOUtil.writeRawVarInt32(out, data.length, LinkedBuffer.allocate(buffer.buffer.length));

    // Write the message data
    out.write(data);

    return data.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new NullPointerException("Output stream, message, schema, and buffer cannot be null.");
    }

    int size = 0;
    try {
        size = schema.writeTo(buffer, message);
        byte[] lengthBuffer = new byte[5]; // Varint max length for int is 5 bytes
        int pos = writeVarInt32(lengthBuffer, size);
        out.write(lengthBuffer, 0, pos);
        out.write(buffer.buffer, 0, size);
    } catch (Exception e) {
        throw new IOException("Error writing message to output stream", e);
    } finally {
        buffer.clear();
    }
    return size;
}

private static int writeVarInt32(byte[] buffer, int value) {
    int pos = 0;
    while (value > 0x7F) {
        buffer[pos++] = (byte) ((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    buffer[pos++] = (byte) value;
    return pos;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Serializes the message into a byte array
    byte[] messageBytes = schema.writeTo(buffer, message);
    int messageSize = messageBytes.length;

    // Prefixes the message with its length
    CodedOutputStream os = CodedOutputStream.newInstance(out);
    os.writeRawVarint32(messageSize);
    os.writeRawBytes(messageBytes);

    // Flushes the output stream
    os.flush();

    // Returns the size of the message
    return messageSize;
}

