static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be a positive integer.");
        }

        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        // Validate month and day
        if (month < 1 || month > 12 || day < 1 || day > 31) {
            throw new IllegalArgumentException("Invalid timeBucket format or value.");
        }

        // Calculate the new day by stepping back to the nearest dayStep
        int newDay = (day - 1) / dayStep * dayStep + 1;

        // Handle the case where the new day might be zero after stepping back
        if (newDay < 1) {
            newDay = 1;
        }

        return year * 10000L + month * 100L + newDay;
    } catch (Exception e) {
        throw new RuntimeException("Error compressing time bucket: " + e.getMessage(), e);
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from timeBucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        // Calculate the new day by subtracting the remainder of day divided by dayStep
        int newDay = day - (day % dayStep);

        // If newDay is 0, it means we need to set it to the previous step's last day
        if (newDay == 0) {
            newDay = dayStep;
        }

        // Return the new time bucket in the same format
        return (year * 10000L) + (month * 100L) + newDay;
    } catch (Exception e) {
        // Handle any potential exceptions, e.g., invalid input format
        throw new IllegalArgumentException("Invalid timeBucket or dayStep provided", e);
    }
}

