                char nextChar = str.charAt(i + 1);
                if (Character.isHighSurrogate(c) && Character.isLowSurrogate(nextChar)) {
                    size += 4; // Full surrogate pair
                    i++; // Skip the next character as it's part of the surrogate pair
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair at the end of the string");
            }
        } else {
            size += 3;
        }
    }
