public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int strlen = str.length();
    int size = 0;

    for (int i = 0; i < strlen; i++) {
        char c = str.charAt(i);
        if (c >= 0 && c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (c >= 0xD800 && c <= 0xDFFF) {
            if (i + 1 < strlen && str.charAt(i + 1) >= 0xDC00 && str.charAt(i + 1) <= 0xDFFF) {
                size += 4;
                i += 1; // Skip the next char as it's a surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid UTF-16 sequence");
            }
        } else {
            size += 3;
        }
    }

    LinkedBuffer buffer = lb;
    int offset = BufferUtil.offset(buffer);
    byte[] data = buffer.buf;

    for (int i = 0; i < strlen; i++) {
        char c = str.charAt(i);

        if (offset >= data.length) {
            buffer = buffer.next = session.nextBuffer(buffer);
            offset = 0;
            data = buffer.buf;
        }

        if (c < 0x80) {
            data[offset++] = (byte) c;
        } else if (c < 0x800) {
            data[offset++] = (byte) (0xC0 | (c >> 6));
            data[offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (c >= 0xD800 && c <= 0xDFFF) {
            if (i + 1 < strlen && str.charAt(i + 1) >= 0xDC00 && str.charAt(i + 1) <= 0xDFFF) {
                int codePoint = Character.toCodePoint(c, str.charAt(i + 1));
                data[offset++] = (byte) (0xF0 | (codePoint >> 18));
                data[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                data[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                data[offset++] = (byte) (0x80 | (codePoint & 0x3F));
                i += 1; // Skip the next char as it's a surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid UTF-16 sequence");
            }
        } else {
            data[offset++] = (byte) (0xE0 | (c >> 12));
            data[offset++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            data[offset++] = (byte) (0x80 | (c & 0x3F));
        }
    }

    BufferUtil.setOffset(buffer, offset);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        final int strLength = str.length();
        int offset = 0;
        LinkedBuffer currentLb = lb;

        while (offset < strLength) {
            int utf8BytesRequired = 0;
            for (int i = offset; i < strLength; i++) {
                char ch = str.charAt(i);
                if (ch < 0x80) utf8BytesRequired++;
                else if (ch < 0x800) utf8BytesRequired += 2;
                else if (Character.isSurrogate(ch)) {
                    if (i + 1 >= strLength) throw new IllegalArgumentException("Invalid surrogate pair sequence");
                    int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
                    utf8BytesRequired += 4;
                    i++; // Skip the next character as it's part of the surrogate pair
                } else utf8BytesRequired += 3;
                if (currentLb.start + utf8BytesRequired > currentLb.limit) {
                    break;
                }
            }

            if (currentLb.start + utf8BytesRequired > currentLb.limit) {
                currentLb = currentLb.next = new LinkedBuffer(currentLb.buffer.length);
            }

            while (offset < strLength) {
                char ch = str.charAt(offset);
                if (ch < 0x80) {
                    currentLb.buffer[currentLb.start++] = (byte) ch;
                } else if (ch < 0x800) {
                    currentLb.buffer[currentLb.start++] = (byte) (0xC0 | (ch >> 6));
                    currentLb.buffer[currentLb.start++] = (byte) (0x80 | (ch & 0x3F));
                } else if (Character.isSurrogate(ch)) {
                    if (offset + 1 >= strLength) throw new IllegalArgumentException("Invalid surrogate pair sequence");
                    int codePoint = Character.toCodePoint(ch, str.charAt(offset + 1));
                    currentLb.buffer[currentLb.start++] = (byte) (0xF0 | (codePoint >> 18));
                    currentLb.buffer[currentLb.start++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    currentLb.buffer[currentLb.start++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    currentLb.buffer[currentLb.start++] = (byte) (0x80 | (codePoint & 0x3F));
                    offset++; // Skip the next character as it's part of the surrogate pair
                } else {
                    currentLb.buffer[currentLb.start++] = (byte) (0xE0 | (ch >> 12));
                    currentLb.buffer[currentLb.start++] = (byte) (0x80 | ((ch >> 6) & 0x3F));
                    currentLb.buffer[currentLb.start++] = (byte) (0x80 | (ch & 0x3F));
                }
                offset++;
            }
        }
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Failed to write UTF8 string to LinkedBuffer", e);
    }
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    final int length = str.length();
    int size = 0;
    for (int i = 0; i < length; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x007F) {
            size++;
        } else if (ch <= 0x07FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < length && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4;
                i++;
            } else {
                throw new IllegalArgumentException("Unpaired surrogate character");
            }
        } else {
            size += 3;
        }
    }

    LinkedBuffer buffer = lb;
    for (int i = 0; i < length; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x007F) {
            buffer = writeByte((byte) ch, session, buffer);
        } else if (ch <= 0x07FF) {
            buffer = writeByte((byte) (0xC0 | (ch >> 6)), session, buffer);
            buffer = writeByte((byte) (0x80 | (ch & 0x3F)), session, buffer);
        } else if (Character.isHighSurrogate(ch)) {
            char lowSurrogate = str.charAt(++i);
            int codePoint = Character.toCodePoint(ch, lowSurrogate);
            buffer = writeByte((byte) (0xF0 | (codePoint >> 18)), session, buffer);
            buffer = writeByte((byte) (0x80 | ((codePoint >> 12) & 0x3F)), session, buffer);
            buffer = writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)), session, buffer);
            buffer = writeByte((byte) (0x80 | (codePoint & 0x3F)), session, buffer);
        } else {
            buffer = writeByte((byte) (0xE0 | (ch >> 12)), session, buffer);
            buffer = writeByte((byte) (0x80 | ((ch >> 6) & 0x3F)), session, buffer);
            buffer = writeByte((byte) (0x80 | (ch & 0x3F)), session, buffer);
        }
    }

    return buffer;
}

private static LinkedBuffer writeByte(byte value, WriteSession session, LinkedBuffer buffer) {
    if (buffer.start + buffer.offset == buffer.limit) {
        buffer = session.next(buffer, 1);
    }
    buffer.buffer[buffer.offset++] = value;
    return buffer;
}

