        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int written = 0;
    try {
        written = com.dyuproject.protostuff.LinkedBuffer.writeUTF8(str, lb);
    } catch (BufferOverflowException e) {
        throw new RuntimeException("Buffer overflow while writing UTF8 string", e);
    }

    session.updateWrittenBytes(written);
    return lb;
