public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    final byte[] utf8Bytes;
    try {
        utf8Bytes = str.toString().getBytes("UTF-8");
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding is not supported", e);
    }

    int index = 0;
    int length = utf8Bytes.length;
    while (index < length) {
        if (lb.start != lb.offset) {
            // If current buffer is not full, write the bytes into it
            int writeLength = Math.min(length - index, lb.limit() - lb.offset);
            System.arraycopy(utf8Bytes, index, lb.buffer, lb.offset, writeLength);
            lb.offset += writeLength;
            index += writeLength;
        } else {
            // If current buffer is full, allocate a new one and link it
            lb = lb.next(session);
        }
    }

    return lb;
}

