public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null; // Key not found in properties
    }

    // Perform variable substitution
    while (true) {
        int start = value.indexOf("${");
        if (start == -1) {
            break;
        }
        int end = value.indexOf("}", start);
        if (end == -1) {
            break; // Malformed variable, no closing brace
        }

        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            varValue = ""; // Variable not found, substitute with empty string
        }

        value = value.substring(0, start) + varValue + value.substring(end + 1);
    }

    return value;
}

public static String findAndSubst(String key, Properties props){
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null; // or throw an exception or return an empty string, depending on requirements
    }

    // Perform variable substitution
    // Assuming the variables are in the form of ${variableName} and are also keys in props
    return value.replaceAll("\\$\\{([^}]*)\\}", match -> {
        String varName = match.group(1);
        String varValue = props.getProperty(varName);
        return varValue != null ? varValue : match.group(0); // keep original if not found
    });
}

