    });
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props must not be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null; // Key not found in properties
    }

    // Perform variable substitution
    StringBuilder result = new StringBuilder();
    int start = 0;
    int openIndex;
    while ((openIndex = value.indexOf("${", start)) != -1) {
        result.append(value, start, openIndex);
        int closeIndex = value.indexOf("}", openIndex + 2);
        if (closeIndex == -1) {
            throw new IllegalArgumentException("Unmatched ${ in property value: " + value);
        }
        String varName = value.substring(openIndex + 2, closeIndex);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            throw new IllegalArgumentException("Variable " + varName + " not found in properties");
        }
        result.append(varValue);
        start = closeIndex + 1;
    }
    result.append(value.substring(start));
    return result.toString();
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null; // or throw an exception if key must exist
    }

    // Perform variable substitution
    // Assuming variables are in the form ${varName}
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        int start = value.indexOf("${", i);
        if (start == -1) {
            result.append(value.substring(i));
            break;
        }
        result.append(value.substring(i, start));
        int end = value.indexOf("}", start + 2);
        if (end == -1) {
            // No closing brace, treat as literal
            result.append(value.substring(start));
            break;
        }
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        result.append(varValue != null ? varValue : ""); // or throw exception if var must exist
        i = end + 1;
    }

    return result.toString();
}

