public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return pathSegments; // Return empty list if path is null or empty
    }
    int start = path.startsWith("/") ? 1 : 0; // Skip leading '/' if present
    int end;
    while (start < path.length()) {
        end = path.indexOf('/', start);
        if (end == -1) {
            end = path.length();
        }
        String segment = path.substring(start, end);
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException("UTF-8 encoding not supported", e);
            }
        }
        pathSegments.add(new PathSegmentImpl(segment));
        start = end + 1;
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    // If the path is absolute, skip the leading '/'
    int start = path.startsWith("/") ? 1 : 0;

    StringBuilder segment = new StringBuilder();
    for (int i = start; i < path.length(); i++) {
        char c = path.charAt(i);
        if (c == '/') {
            String segmentStr = segment.toString();
            if (decode) {
                try {
                    segmentStr = URLDecoder.decode(segmentStr, StandardCharsets.UTF_8.toString());
                } catch (UnsupportedEncodingException e) {
                    throw new RuntimeException("UTF-8 encoding not supported", e);
                }
            }
            pathSegments.add(new PathSegmentImpl(segmentStr));
            segment.setLength(0); // Reset the StringBuilder for the next segment
        } else {
            segment.append(c);
        }
    }

    // Add the last segment (if any)
    String lastSegment = segment.toString();
    if (decode) {
        try {
            lastSegment = URLDecoder.decode(lastSegment, StandardCharsets.UTF_8.toString());
        } catch (UnsupportedEncodingException e) {
            throw new RuntimeException("UTF-8 encoding not supported", e);
        }
    }
    if (!lastSegment.isEmpty()) {
        pathSegments.add(new PathSegmentImpl(lastSegment));
    }

    return pathSegments;
}

