    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return pathSegments; // Return empty list if path is null or empty
    }

    // If the path is absolute, ignore the leading '/'
    int startIndex = path.startsWith("/") ? 1 : 0;

    String[] segments = path.substring(startIndex).split("/");

    for (String segment : segments) {
        try {
            String decodedSegment = decode ? URLDecoder.decode(segment, StandardCharsets.UTF_8.toString()) : segment;
