public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    float x = box.x;
    float y = box.y;
    float width = box.width;
    float height = box.height;

    if (width < 0) {
        throw new IllegalArgumentException("Box width cannot be negative");
    }

    float halfWidth = width / 2.0f;

    Box2D leftBox = new Box2D(x, y, halfWidth, height);
    Box2D rightBox = new Box2D(x + halfWidth, y, halfWidth, height);

    return new Pair<>(leftBox, rightBox);
}

