@Override public String readString() throws IOException {
    int length = 0;
    int b;
    // Read the length of the string (assuming it's encoded in a simple way, e.g., as a 4-byte integer)
    for (int i = 0; i < 4; i++) {
        b = this.read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading string length");
        }
        length = (length << 8) + (b & 0xFF);
    }

    if (length < 0) {
        throw new IOException("Invalid string length: " + length);
    }

    byte[] bytes = new byte[length];
    int bytesRead = 0;
    while (bytesRead < length) {
        b = this.read(bytes, bytesRead, length - bytesRead);
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading string data");
        }
        bytesRead += b;
    }

    return new String(bytes, StandardCharsets.UTF_8);
}

