private static String javaCharset(String charset) {
    if (charset == null) {
        return null;
    }
    switch (charset.toLowerCase().trim()) {
        case "iso-8859-1":
            return "ISO-8859-1";
        case "us-ascii":
            return "US-ASCII";
        case "utf-8":
            return "UTF-8";
        case "utf-16":
            return "UTF-16";
        case "utf-16be":
            return "UTF-16BE";
        case "utf-16le":
            return "UTF-16LE";
        default:
            throw new IllegalArgumentException("Unknown charset: " + charset);
    }
}

private static String javaCharset(String charset){
    if (charset == null) {
        throw new IllegalArgumentException("Charset cannot be null");
    }

    switch (charset.toLowerCase()) {
        case "utf-8":
            return "UTF-8";
        case "iso-8859-1":
            return "ISO-8859-1";
        case "us-ascii":
            return "US-ASCII";
        case "utf-16":
            return "UTF-16";
