private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start node, and stop node must not be null");
    }
    if (dir < 0) {
        throw new IllegalArgumentException("Direction must be a non-negative integer");
    }

    Node currentNode = start;
    OuterFaceCirculator circulator = new OuterFaceCirculator(currentNode, dir);

    do {
        if (predicate.test(currentNode)) {
            return circulator;
        }
        currentNode = circulator.next();
    } while (currentNode != stop && currentNode != start);

    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start, and stop nodes must not be null");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    do {
        if (predicate.test(circulator.node())) {
            return circulator;
        }
        circulator.advance();
    } while (!circulator.node().equals(stop));

    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start, and stop nodes must not be null");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node currentNode = circulator.currentNode();

    while (currentNode != stop && !predicate.test(currentNode)) {
        circulator.advance();
        currentNode = circulator.currentNode();

        // Prevent infinite loop in case of disconnected or misconfigured graph
        if (currentNode == start) {
            throw new IllegalStateException("Reached start node again without finding stop node or satisfying predicate");
        }
    }

    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    try {
        if (start == null || stop == null || predicate == null) {
            throw new IllegalArgumentException("Start, stop nodes, and predicate cannot be null");
        }

        OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
        while (!circulator.getNode().equals(stop)) {
            if (predicate.test(circulator.getNode())) {
                return circulator;
            }
            circulator.moveToNext();
        }
        return circulator;
    } catch (Exception e) {
        throw new RuntimeException("Error occurred during node selection", e);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start, and stop nodes must not be null.");
    }
    if (start == stop) {
        return new OuterFaceCirculator(stop, dir);
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    do {
        if (predicate.test(circulator.currentNode())) {
            return circulator;
        }
        circulator.moveNext();
    } while (circulator.currentNode() != stop);

    return circulator;
}

