protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edges = new ArrayList<>(tour);
    V startVertex = null;
    V lastVertex = null;

    // Find a starting point
    for (E edge : edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null && graph.incomingEdgesOf(source).size() == 1) {
            startVertex = source;
        }
        if (graph.outgoingEdgesOf(target).size() == 1) {
            lastVertex = target;
        }
    }

    if (startVertex == null) {
        // If no clear start vertex, use the source of the first edge
        startVertex = graph.getEdgeSource(edges.get(0));
    }

    // Reconstruct the path
    List<E> pathEdges = new ArrayList<>();
    V currentVertex = startVertex;
    while (currentVertex != null) {
        E nextEdge = null;
        for (E edge : graph.outgoingEdgesOf(currentVertex)) {
            if (tour.contains(edge)) {
                nextEdge = edge;
                pathEdges.add(edge);
                tour.remove(edge);
                break;
            }
        }
        currentVertex = (nextEdge != null) ? graph.getEdgeTarget(nextEdge) : null;
    }

    if (pathEdges.isEmpty()) {
        throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
    }

    V endVertex = graph.getEdgeTarget(pathEdges.get(pathEdges.size() - 1));
    if (!endVertex.equals(lastVertex) && lastVertex != null) {
        throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
    }

    double weight = pathEdges.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, startVertex, pathEdges, weight);
}

