        }
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            startVertex = source;
            pathVertices.add(startVertex);
        }

        if (!pathVertices.get(pathVertices.size() - 1).equals(source)) {
            throw new IllegalArgumentException("Edges in tour are not connected");
        }

        pathVertices.add(target);
    }

    // Check if the tour forms a cycle
    if (!pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1))) {
        throw new IllegalArgumentException("Tour is not a cycle");
    }

