    List<E> pathEdges = new ArrayList<>(tour);
    List<V> pathVertices = new ArrayList<>();
    Map<V, Integer> visitedVertices = new HashMap<>();

    V startVertex = null;
    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (!visitedVertices.containsKey(source)) {
            startVertex = source;
            break;
        } else if (!visitedVertices.containsKey(target)) {
            startVertex = target;
            break;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("The set of edges does not form a valid tour");
    }

    V currentVertex = startVertex;
    pathVertices.add(currentVertex);
    visitedVertices.put(currentVertex, pathVertices.size() - 1);

    while (pathEdges.size() > 0) {
        E nextEdge = null;
        for (E edge : pathEdges) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);

            if (source.equals(currentVertex) || target.equals(currentVertex)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("The set of edges does not form a valid tour");
        }

        V oppositeVertex = (graph.getEdgeSource(nextEdge).equals(currentVertex)) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);

        pathEdges.remove(nextEdge);
        pathVertices.add(oppositeVertex);
        visitedVertices.put(oppositeVertex, pathVertices.size() - 1);

        currentVertex = oppositeVertex;
    }

    if (!pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1))) {
        throw new IllegalArgumentException("The set of edges does not form a valid tour");
    }

    double weight = 0;
    for (E edge : pathEdges) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, pathVertices.get(0), pathVertices, weight);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    Map<V, Integer> degreeMap = new HashMap<>();

    // Calculate the degree of each vertex
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        degreeMap.put(source, degreeMap.getOrDefault(source, 0) + 1);
        degreeMap.put(target, degreeMap.getOrDefault(target, 0) + 1);
    }

    // Find the starting vertex (a vertex with odd degree or any vertex if all have even degree)
    for (Map.Entry<V, Integer> entry : degreeMap.entrySet()) {
        if (entry.getValue() % 2 != 0) {
            startVertex = entry.getKey();
            break;
        }
    }
    if (startVertex == null) {
        startVertex = edgeList.get(0).getSource();
    }

    // Construct the path using Hierholzer's algorithm
    List<E> path = new ArrayList<>();
    Stack<E> stack = new Stack<>();
    stack.push(edgeList.get(0));
    while (!stack.isEmpty()) {
        E e = stack.peek();
        V currentVertex = graph.getEdgeSource(e).equals(startVertex) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
        List<E> adjacentEdges = new ArrayList<>(graph.edgesOf(currentVertex));
        adjacentEdges.removeAll(path);

        if (!adjacentEdges.isEmpty()) {
            E nextEdge = adjacentEdges.get(0);
            stack.push(nextEdge);
            path.add(nextEdge);
        } else {
            path.add(stack.pop());
        }
    }

    // Reverse the path to get the correct order
    Collections.reverse(path);

    // Ensure the path forms a cycle
    if (!graph.getEdgeTarget(path.get(path.size() - 1)).equals(graph.getEdgeSource(path.get(0)))) {
        throw new IllegalArgumentException("The edge set does not form a valid tour");
    }

    return new GraphPathImpl<>(graph, graph.getEdgeSource(path.get(0)), path, 0.0);
}

