private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    boolean escapeMode = false;
    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);
        if (escapeMode) {
            output.append(currentChar);
            escapeMode = false;
        } else if (currentChar == '\\') {
            escapeMode = true;
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    boolean escapeMode = false;
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            escapeMode = true;
        } else {
            if (escapeMode) {
                // Unescape the character
                // For simplicity, we assume that only double quotes and backslashes need to be unescaped
                switch (c) {
                    case '"':
                    case '\\':
                        result.append(c);
                        break;
                    default:
                        // If the character is not a known escape sequence, just append it
                        result.append('\\');
                        result.append(c);
                        break;
                }
            } else {
                result.append(c);
            }
            escapeMode = false;
        }
    }
    return result.toString();
}

private String unescapeId(String input){
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }
    StringBuilder result = new StringBuilder();
    boolean escapeMode = false;
    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);
        if (escapeMode) {
            if (currentChar == '\\') {
                result.append('\\');
            } else if (currentChar == '.') {
                result.append('.');
            } else {
                throw new IllegalArgumentException("Invalid escape sequence: \\" + currentChar);
            }
            escapeMode = false;
        } else {
            if (currentChar == '\\') {
                escapeMode = true;
            } else {
                result.append(currentChar);
            }
        }
    }
    if (escapeMode) {
        throw new IllegalArgumentException("Unterminated escape sequence");
    }
    return result.toString();
}

private String unescapeId(String input){
