    try {
        if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
        Set<Integer> targetBucket = bucketsByLabel.get(0);

        if (sourceBucket == null || targetBucket == null) {
            throw new IllegalStateException("Buckets are not properly initialized");
        }

        for (Integer vertex : sourceBucket) {
            if (vertex < 0 || vertex >= labels.size()) {
                throw new IllegalArgumentException("Vertex index out of bounds");
            }
            labels.set(vertex, 0);
            targetBucket.add(vertex);
        }

        sourceBucket.clear();
    } catch (Exception e) {
        e.printStackTrace();
    }
}

