public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and JScrollPane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index is out of bounds");
    }

    table.getSelectionModel().setSelectionInterval(row, row);
    Rectangle rect = table.getCellRect(row, 0, true);
    pane.getViewport().scrollRectToVisible(rect);

    // Delayed repaint to ensure the table properly paints the newly selected row
    table.repaint(rect);

    // Additional delay to handle offscreen painting
    try {
        Thread.sleep(50); // 50 milliseconds delay
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }

    table.repaint(rect);
}

