    }

    // Find the first space after the nameStart
    int spaceIndex = buf.indexOf(" ", nameStart);
    if (spaceIndex == -1) {
        // No space found, abbreviate the whole string from nameStart
        char firstChar = buf.charAt(nameStart);
        buf.replace(nameStart, buf.length(), String.valueOf(firstChar).toUpperCase());
    } else {
