    int vertexCount = vertices.size();
    for (V vertex : vertices) {
        Set<V> neighbors = new HashSet<>(Graphs.neighborListOf(graph, vertex));
        neighbors.retainAll(vertices);
        if (neighbors.size() != vertexCount - 1) {
            return false;
        }
    }

    return true;
}

