    }

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // This is a method descriptor
        index = 1;
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
        index++; // Move past the ')'
    }

    // If there's a return type, pop it as well
    if (index < descriptor.length()) {
        popType(descriptor, index);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
        case 'F':
            index++; // These are single-byte types
            break;
        case 'D':
        case 'J':
            index++; // These are double-word types
            break;
        case 'L':
            // Object type, parse to end of class descriptor
            index = descriptor.indexOf(';', index) + 1;
            break;
        case '[':
            // Array type, skip to the element type
            index++;
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

private void pop(final String descriptor) {
