                    // Single width types
                    break;
                case 'D': case 'J':
                    // Double width types
                    break;
                case 'L':
                    // Object type
                    break;
                case '[':
                    // Array type
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type descriptor: " + descriptor.charAt(0));
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
