private void popTypes(String types) {
    for (int i = 0; i < types.length(); i++) {
        char type = types.charAt(i);
        switch (type) {
            case '[': // array
                // Arrays are represented by a '[', followed by the type of the array elements
                while (types.charAt(i) == '[') {
                    i++;
                    if (i >= types.length()) {
                        throw new IllegalArgumentException("Invalid type descriptor: array type not specified");
                    }
                }
                // The element type is now at index i, which will be handled in the next iteration
                i--;
                break;
            case 'B': // byte
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                // These types take up one slot in the stack frame
                // No further processing needed for these
                break;
            case 'L': // reference type
                // Reference types are represented by 'L', followed by the fully qualified class name, followed by ';'
                while (types.charAt(i) != ';') {
                    i++;
                    if (i >= types.length()) {
                        throw new IllegalArgumentException("Invalid type descriptor: missing ';'");
                    }
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid type descriptor character: " + type);
        }
        // Each valid type descriptor character decreases the stack size by one
        // Double and long actually take up two slots, but the stack frame representation in this method is simplified
    }
}

