private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
            // Each of these is a single-slot type
            index++;
            break;
        case 'J': case 'D':
            // Each of these is a double-slot type
            index++;
            break;
        case 'L': // Object type
            index = descriptor.indexOf(';', index) + 1;
            if (index == 0) {
                throw new IllegalArgumentException("Invalid object descriptor");
            }
            break;
        case '[': // Array type
            index++;
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Unknown type descriptor: " + descriptor.charAt(index));
    }
    return index;
