    // Apply the relative path components
    for (String component : relativePathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            if (component.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else {
                stack.push(component);
            }
        }
    }

    // Reconstruct the full path
    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        result.insert(0, stack.pop());
        if (!stack.isEmpty()) {
